        c.x *= 1.6;
        float r = 0.04 + 0.09 * hash21(vec2(fi, 3.3));
        float d = length(uv - c);
        float glow = r * r / (d * d + 0.001);
        vec3 tint = palette(hash21(vec2(fi, 4.4)), vec3(0.55, 0.5, 0.45), vec3(0.4, 0.35, 0.3), vec3(1.0), vec3(0.05, 0.2, 0.4));
        col += tint * glow * 0.04;
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float clear = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        vec2 p = uv * (2.0 + fi * 1.5);
        p.y += iTime * (0.3 + fi * 0.2);
        clear += amp * noise(p);
        amp *= 0.55;
    }
    clear = smoothstep(0.3, 0.9, clear);
    vec3 sharp = bokehBG(uv);
    vec3 blurred = bokehBG(uv * 0.4) * 0.6 + vec3(0.03);
    vec3 col = mix(blurred, sharp, clear);
    float drips = fbm(uv * vec2(6.0, 2.0) + vec2(0.0, iTime * 1.2));
    col += smoothstep(0.75, 0.85, drips) * 0.15;
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 hash2(vec2 p) {
    return vec2(hash21(p), hash21(p + vec2(17.0, 31.0)));
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float voronoi(vec2 p, float t, out vec2 cellCenter) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minD = 8.0;
    vec2 minPoint = vec2(0.0);
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 pt = hash2(ip + neighbor);
            pt = 0.5 + 0.5 * sin(t * 0.4 + 6.2831 * pt);
            vec2 diff = neighbor + pt - fp;
            float d = length(diff);
            if (d < minD) {
                minD = d;
                minPoint = ip + neighbor + pt;
            }
        }
    }
    cellCenter = minPoint;
    return minD;
}

vec3 bokehBG(vec2 uv) {
    vec3 col = vec3(0.02, 0.02, 0.05);
    for (int i = 0; i < 12; i++) {
        float fi = float(i);
        vec2 c = vec2(hash21(vec2(fi, 1.5)) * 2.0 - 1.0, hash21(vec2(fi, 2.5)) * 2.0 - 1.0);
        c.x *= 1.6;
        float r = 0.04 + 0.08 * hash21(vec2(fi, 3.5));
        float d = length(uv - c);
        float glow = r * r / (d * d + 0.001);
        vec3 tint = palette(hash21(vec2(fi, 4.5)), vec3(0.55, 0.5, 0.45), vec3(0.4, 0.35, 0.3), vec3(1.0), vec3(0.05, 0.2, 0.4));
        col += tint * glow * 0.045;
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 guv = uv * 5.0;
    guv.y += iTime * 0.6;
    vec2 cellCenter;
    float d = voronoi(guv, iTime, cellCenter);
    float mask = smoothstep(0.5, 0.1, d);
    vec2 refr = (guv - cellCenter) * mask;
    vec3 col = bokehBG(uv + refr * 0.15);
    col += mask * 0.25 * vec3(0.9, 0.95, 1.0);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

vec3 bokehPolar(vec2 uv, float t) {
    vec3 col = vec3(0.02, 0.02, 0.05);
    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        float ring = 0.25 + 0.55 * hash21(vec2(fi, 2.0));
        float ang = 6.2831 * hash21(vec2(fi, 9.0)) + t * 0.04 * hash21(vec2(fi, 3.0));
        vec2 c = ring * vec2(cos(ang), sin(ang));
        c.x *= 1.6;
        float r = 0.04 + 0.08 * hash21(vec2(fi, 4.0));
        float d = length(uv - c);
        float glow = r * r / (d * d + 0.001);
        vec3 tint = palette(hash21(vec2(fi, 6.0)), vec3(0.55, 0.5, 0.45), vec3(0.4, 0.4, 0.3), vec3(1.0), vec3(0.1, 0.2, 0.3));
        col += tint * glow * 0.04;
    }
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float a = atan(uv.y, uv.x);
    float ripple = sin(r * 20.0 - iTime * 3.0) * 0.002 * smoothstep(0.6, 0.0, r);
    vec2 dir = uv / (r + 0.0001);
    vec2 duv = uv + dir * ripple;
    vec3 col = bokehPolar(duv, iTime);
    float streaks = fract(a * 8.0 / 6.2831 + iTime * 0.3 + r * 2.0);
    float line = smoothstep(0.0, 0.03, streaks) * smoothstep(0.09, 0.06, streaks);
    col += line * 0.08 * smoothstep(1.0, 0.2, r);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 0.0, -1.0);
    vec3 rd = normalize(vec3(uv, 1.2));
    float t = 0.0;
    float density = 0.0;
    for (int i = 0; i < 32; i++) {
        vec3 p = ro + rd * t;
        float n = fbm(p.xy * 0.8 + vec2(0.0, iTime * 0.15) + p.z * 0.1);
        float d = n * 0.5 - 0.15;
        density += max(d, 0.0) * 0.05;
        t += 0.15;
        if (t > 4.5) break;
    }

    vec3 bokehCol = vec3(0.0);
    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        vec3 lp = vec3((hash21(vec2(fi, 1.0)) * 2.0 - 1.0) * 1.8, (hash21(vec2(fi, 2.0)) * 2.0 - 1.0) * 1.0, 1.5 + 2.5 * hash21(vec2(fi, 3.0)));
        vec2 proj = lp.xy / lp.z;
        float r = 0.03 * lp.z + 0.02;
        float d = length(uv - proj);
        float glow = r * r / (d * d + 0.001);
        vec3 tint = palette(hash21(vec2(fi, 5.0)), vec3(0.55, 0.5, 0.45), vec3(0.4, 0.4, 0.3), vec3(1.0), vec3(0.1, 0.25, 0.4));
        bokehCol += tint * glow * 0.03;
    }

    vec3 col = bokehCol * (1.0 - density * 0.6) + vec3(0.02, 0.02, 0.05);

    vec2 ruv = uv * vec2(10.0, 1.0);
    ruv.y += iTime * 2.0;
    vec2 rid = floor(ruv);
    vec2 rf = fract(ruv);
    float streak = hash21(rid);
    float line = smoothstep(0.0, 0.05, rf.x) * smoothstep(0.12, 0.07, rf.x);
    col += line * 0.06 * step(0.6, streak);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
